/* Build PSL data for site identity and filter exception scope.
   --check validates the shipped generated file offline. */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'psl-private.js');
const DOMAIN = path.join(ROOT, 'domain-utils.js');
const SOURCE_URL = 'https://publicsuffix.org/list/public_suffix_list.dat';
const BEGIN = '// ===BEGIN PRIVATE DOMAINS===';
const END = '// ===END PRIVATE DOMAINS===';
// A shipped list older than this fails --check: the point of generating it is that it stays
// current, and a stale copy is the hand-maintained table again with extra steps.
const MAX_AGE_DAYS = 400;
// Suffixes the check insists on. If any of these is missing the file was built from the wrong
// section, or the parse silently threw everything away.
const MUST_CONTAIN = ['github.io', 'webflow.io', 'netlify.app', 'pages.dev', 'vercel.app', 'herokuapp.com'];

const args = process.argv.slice(2);
const flag = (name) => args.includes(name);
const option = (name) => { const at = args.indexOf(name); return at >= 0 ? args[at + 1] : ''; };

function toAscii(label) {
  // The URL parser is the one IDNA implementation every context here agrees with.
  try { return new URL('http://' + label + '/').hostname; } catch (_) { return ''; }
}

function parsePrivateRules(text, section = 'PRIVATE') {
  const lines = String(text || '').split(/\r?\n/);
  const start = lines.findIndex((l) => l.trim() === BEGIN.replace('PRIVATE', section));
  const end = lines.findIndex((l) => l.trim() === END.replace('PRIVATE', section));
  if (start < 0 || end < 0 || end <= start) throw new Error('private-domains section markers not found');
  const versionLine = lines.find((l) => /^\/\/ VERSION:/.test(l.trim()));
  const version = versionLine ? versionLine.replace(/^\/\/ VERSION:\s*/, '').trim() : '';
  if (!/^\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}_UTC$/.test(version)) throw new Error('no VERSION stamp in the list header: ' + JSON.stringify(version));
  const rules = new Set();
  for (const raw of lines.slice(start + 1, end)) {
    const line = raw.trim();
    if (!line || line.startsWith('//')) continue;
    let prefix = '';
    let body = line;
    if (body.startsWith('!')) { prefix = '!'; body = body.slice(1); }
    else if (body.startsWith('*.')) { prefix = '*.'; body = body.slice(2); }
    const ascii = toAscii(body.toLowerCase());
    if (!ascii || !/^[a-z0-9.-]+$/.test(ascii) || ascii.includes('..')) throw new Error('rule did not survive normalisation: ' + line);
    rules.add(prefix + ascii);
  }
  if (rules.size < 1000) throw new Error('only ' + rules.size + ' private rules parsed; the section markers or format changed');
  return { version, rules: Array.from(rules).sort() };
}

function render(version, rules, icannRules) {
  return [
    '/* WardenOne — Copyright (C) 2026 iri',
    '   Licensed under the GNU General Public License v3 or later. See LICENSE.',
    '   Official source: https://github.com/iri-dev/WardenOne',
    '   Upstream filter-list attribution: CREDITS.md',
    '   Redistributing a modified copy? GPLv3 section 5(a) requires you to mark it as changed,',
    '   with the date, and to keep these notices intact. */',
    '/* GENERATED by tools/build-psl.js -- do not edit by hand.',
    '   Public Suffix List data (https://publicsuffix.org, Mozilla Foundation, MPL-2.0), sorted in',
    '   punycode. Private rules separate tenants; ICANN rules constrain filter exceptions.',
    '   Trusted contexts load this form; every world uses its generated compact boundaries.',
    '   To update: node tools/build-psl.js, then review the',
    '   printed additions and removals before committing. */',
    "const WARDENONE_PSL_VERSION = '" + version + "';",
    'const WARDENONE_PSL_PRIVATE_RULES = [',
    ...rules.map((r) => "  '" + r + "',"),
    "].join('\\n');",
    'const WARDENONE_PSL_ICANN_RULES = [',
    ...icannRules.map((r) => "  '" + r + "',"),
    "].join('\\n');",
    '',
  ].join('\n');
}

function renderGroups(version, rules, section) {
  const groups = Object.create(null);
  for (const rule of rules) {
    const dot = rule.lastIndexOf('.');
    if (dot < 0) continue; // Single-label rules are covered by the PSL default '*'.
    const tld = rule.slice(dot + 1);
    (groups[tld] ||= []).push(rule.slice(0, dot));
  }
  return [
    '/* BEGIN GENERATED ' + section + ' PSL — tools/build-psl.js',
    '   Public Suffix List contributors, MPL-2.0: https://publicsuffix.org/list/public_suffix_list.dat',
    '   Source version: ' + version + '. Grouped by TLD; single-label rules use the default wildcard. */',
    'const WARDENONE_' + section + '_GROUPS = Object.freeze({',
    ...Object.keys(groups).sort().map((tld) => '  ' + JSON.stringify(tld) + ': ' + JSON.stringify(groups[tld].join('|')) + ','),
    '});',
    '/* END GENERATED ' + section + ' PSL */',
  ].join('\n');
}

function domainWithPsl(version, icannRules, privateRules) {
  const source = fs.readFileSync(DOMAIN, 'utf8');
  const region = /\/\* BEGIN GENERATED ICANN PSL[\s\S]*?\/\* END GENERATED ICANN PSL \*\//;
  if (!region.test(source)) throw new Error('domain-utils.js ICANN data markers are missing');
  const icann = source.replace(region, renderGroups(version, icannRules, 'ICANN'));
  const privateRegion = /\/\* BEGIN GENERATED PRIVATE PSL[\s\S]*?\/\* END GENERATED PRIVATE PSL \*\//;
  if (!privateRegion.test(icann)) throw new Error('domain-utils.js private data markers are missing');
  return icann.replace(privateRegion, renderGroups(version, privateRules, 'PRIVATE'));
}

function readShipped() {
  if (!fs.existsSync(OUT)) return null;
  const text = fs.readFileSync(OUT, 'utf8');
  const version = (text.match(/^const WARDENONE_PSL_VERSION = '([^']*)';$/m) || [])[1] || '';
  const body = text.slice(text.indexOf('const WARDENONE_PSL_PRIVATE_RULES = [') , text.indexOf("].join('\\n');"));
  const rules = [];
  for (const line of body.split('\n')) {
    const m = line.match(/^  '([^']+)',$/);
    if (m) rules.push(m[1]);
  }
  const icannBody = text.slice(text.indexOf('const WARDENONE_PSL_ICANN_RULES = ['));
  const icannRules = Array.from(icannBody.matchAll(/^  '([^']+)',$/gm), (m) => m[1]);
  return { text, version, rules, icannRules };
}

function versionDate(version) {
  const m = /^(\d{4})-(\d{2})-(\d{2})_/.exec(version || '');
  return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : NaN;
}

function check() {
  const shipped = readShipped();
  const problems = [];
  if (!shipped) { console.error('psl-private.js is missing; run node tools/build-psl.js'); process.exit(1); }
  if (!/^\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}_UTC$/.test(shipped.version)) problems.push('version stamp is malformed: ' + JSON.stringify(shipped.version));
  const age = (Date.now() - versionDate(shipped.version)) / 86400000;
  if (!(age < MAX_AGE_DAYS)) problems.push('shipped list is ' + Math.round(age) + ' days old (limit ' + MAX_AGE_DAYS + '); run node tools/build-psl.js');
  if (shipped.rules.length < 1000) problems.push('only ' + shipped.rules.length + ' rules in the shipped file');
  if (shipped.icannRules.length < 5000) problems.push('ICANN suffix data is missing or incomplete');
  for (const group of [shipped.rules, shipped.icannRules]) {
    const sorted = group.slice().sort();
    if (sorted.some((r, i) => r !== group[i])) problems.push('rules are not sorted; regenerate the file');
    if (new Set(group).size !== group.length) problems.push('duplicate rules');
  }
  for (const r of shipped.rules.concat(shipped.icannRules)) {
    const body = r.replace(/^(!|\*\.)/, '');
    if (!/^[a-z0-9.-]+$/.test(body) || body.includes('..') || body.startsWith('.') || body.endsWith('.')) { problems.push('rule is not a punycode hostname: ' + r); break; }
    if (/[^\x00-\x7f]/.test(r)) { problems.push('rule is not ASCII: ' + r); break; }
  }
  for (const s of MUST_CONTAIN) if (!shipped.rules.includes(s)) problems.push('expected private suffix missing: ' + s);
  for (const s of ['com', 'co.uk', 'k12.ca.us', '*.ck', '!www.ck']) if (!shipped.icannRules.includes(s)) problems.push('expected ICANN suffix missing: ' + s);
  if (shipped.text !== render(shipped.version, shipped.rules, shipped.icannRules)) problems.push('file body differs from what the generator renders for its own rules; regenerate it');
  if (fs.readFileSync(DOMAIN, 'utf8') !== domainWithPsl(shipped.version, shipped.icannRules, shipped.rules)) problems.push('domain-utils.js compact data differs from the shipped list; run --from-shipped, then rebuild content');
  if (problems.length) {
    for (const p of problems) console.error('psl-private.js: ' + p);
    process.exit(1);
  }
  console.log('psl-private.js ok: ' + shipped.rules.length + ' private rules, list version ' + shipped.version + ', ' + Math.round(age) + ' days old');
}

async function fetchList() {
  const res = await fetch(SOURCE_URL, { headers: { 'user-agent': 'WardenOne build (tools/build-psl.js)' } });
  if (!res.ok) throw new Error('fetch failed: HTTP ' + res.status);
  return res.text();
}

async function build() {
  if (flag('--from-shipped')) {
    const shipped = readShipped();
    if (!shipped || !shipped.icannRules.length) throw new Error('shipped ICANN data is missing');
    fs.writeFileSync(DOMAIN, domainWithPsl(shipped.version, shipped.icannRules, shipped.rules));
    fs.writeFileSync(OUT, render(shipped.version, shipped.rules, shipped.icannRules));
    console.log('rebuilt full and compact data from the shipped PSL snapshot');
    return;
  }
  const from = option('--from');
  const text = from ? fs.readFileSync(path.resolve(from), 'utf8') : await fetchList();
  const parsed = parsePrivateRules(text);
  const icann = parsePrivateRules(text, 'ICANN');
  const prior = readShipped();
  const next = render(parsed.version, parsed.rules, icann.rules);
  fs.writeFileSync(DOMAIN, domainWithPsl(parsed.version, icann.rules, parsed.rules));
  if (prior) {
    console.log('list version ' + (prior.version || '(none)') + ' -> ' + parsed.version);
    for (const [label, previous, current] of [['private', prior.rules, parsed.rules], ['ICANN', prior.icannRules, icann.rules]]) {
      const before = new Set(previous), after = new Set(current);
      const added = current.filter((r) => !before.has(r)), removed = previous.filter((r) => !after.has(r));
      console.log(label + ' rules ' + previous.length + ' -> ' + current.length + ' (' + added.length + ' added, ' + removed.length + ' removed)');
      // A removed suffix widens trust; print every change for review.
      for (const r of added) console.log('  + ' + r);
      for (const r of removed) console.log('  - ' + r);
    }
    if (prior.text === next) { console.log('psl-private.js is already current'); return; }
  }
  fs.writeFileSync(OUT, next);
  console.log('wrote ' + path.relative(ROOT, OUT) + ' (' + parsed.rules.length + ' rules, ' + next.length + ' bytes)');
}

if (flag('--check')) check();
else build().catch((err) => { console.error('build-psl: ' + (err && err.message || err)); process.exit(1); });
